Definition sd_segB_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LF : list fframe) (lo shi implb spa ff fp : Z) (Q : mem -> Prop) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch (sdB_W lo spa implb ff fp) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ Q m'
    /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi.
Scheme kc__1 := Elimination for Corelib.Init.Logic.and Sort Prop.
Scheme kc__2 := Elimination for Corelib.Init.Datatypes.bool Sort Prop.

(* [comment removed for export] *)
Lemma sd_exit : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (rax t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' w16 xs1 xs3 xs4 xs5 xs6 xs10 xs11 : word)
    (implb spa lo shi ff fp : Z) (LF : list fframe) (Q : mem -> Prop)
    (m mx : mem) (lowpad gap : list cell) (hjunk sh16 : list byte) (bflag : byte),
  rw_cells bsegs mx spa lowpad -> Z.of_nat (cells_size lowpad) = 16 -> lo <= spa ->
  rw_cells bsegs mx (spa + 16) [C8 w16] ->
  rw_cells bsegs mx (spa + 24) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -128 - spa -> spa <= bv_unsigned sp + -128 ->
  rw_cells bsegs mx (bv_unsigned sp + -104) (sd_saved s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
  rw_cells bsegs mx ff [CB 120 hjunk; C8 (Z_to_bv 64 fp)] ->
  rw_cells bsegs mx (Z.shiftr ff 3 + 2147450880) [CB 16 sh16] ->
  rw_cells bsegs mx fp [C1 bflag] ->
  stk bsegs mx lo spa -> mem_inv bsegs mx ->
  as_RFS H ((1, ff, fp) :: LF) mx -> fresh_frame H LF 1 ff fp -> ACONST mx -> stack0 mx lo shi ->
  munch (sdB_W lo spa implb ff fp) m mx -> wmono bsegs m mx ->
  (forall m', munch [(ff, ff + 8); (Z.shiftr ff 3 + 2147450880, Z.shiftr ff 3 + 2147450880 + 16); (fp, fp + 1)]%Z mx m' -> wmono bsegs mx m' -> Q m') ->
  lo + 144 <= bv_unsigned sp -> aceil <= lo -> bv_unsigned ra mod 2 = 0 ->
  evt bsegs (sd_segB_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LF lo shi implb spa ff fp Q m)
    (MS (mkR rax (Z_to_bv 64 spa) gp tp t0' t1' t2' sp xs1 a0' a1' a2' a3' a4' a5' a6' a7'
             (Z_to_bv 64 ff) xs3 xs4 xs5 xs6 (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 2147450880) (Z_to_bv 64 ff) xs10 xs11 t3' t4' t5' t6')
        F (Z_to_bv 64 ASD_EXIT) fc None mx (seg_rom bsegs)).
