Lemma sd_segB : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (pcv rax t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' xs1 xs4 xs5 xs6 xs10 xs11 w16 : word)
    (stb implb ioc lk ivp iu ii spa lo shi ff fp : Z) (LF : list fframe)
    (m mx : mem) (lowpad gap : list cell) (hjunk sh16 j16 ij7 : list byte) (bflag : byte),
  (pcv = Z_to_bv 64 ASD_B \/ pcv = ret_pc (Z_to_bv 64 ASD_B)) ->
  rw_cells bsegs mx spa lowpad -> Z.of_nat (cells_size lowpad) = 16 -> lo <= spa ->
  rw_cells bsegs mx (spa + 16) [C8 w16] ->
  rw_cells bsegs mx (spa + 24) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -128 - spa -> spa <= bv_unsigned sp + -128 -> bv_unsigned sp + -144 <= spa -> spa mod 16 = 0 ->
  rw_cells bsegs mx (bv_unsigned sp + -104) (sd_saved s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
  rw_cells bsegs mx ff [CB 120 hjunk; C8 (Z_to_bv 64 fp)] ->
  rw_cells bsegs mx (Z.shiftr ff 3 + 2147450880) [CB 16 sh16] ->
  rw_cells bsegs mx fp [C1 bflag] ->
  stk bsegs mx lo spa -> mem_inv bsegs mx ->
  as_RFS H ((1, ff, fp) :: LF) mx -> fresh_frame H LF 1 ff fp -> ACONST mx -> stack0 mx lo shi -> as_RFS H LF m ->
  (* [comment removed for export] *)
  rw_cells bsegs mx (stb + 32) (AnyExecCells (stb + 32) ioc j16) ->
  rw_cells bsegs mx (stb + 88) [C8 (wz (implb + 32)); C8 (wz implb)] ->
  APMutex mx (stb + 104) lk ->
  aapp stb SZ_SPCI_STATE -> stb mod 16 = 0 -> addressable mx stb SZ_SPCI_STATE -> fsobj H LF stb SZ_SPCI_STATE ->
  (* [comment removed for export] *)
  rw_cells bsegs mx implb (SpcHdrCells (mkSPC ivp iu 2 ii) ij7) -> spc_ok (mkSPC ivp iu 2 ii) ->
  aapp implb SZ_SPCI_IMPL -> implb mod 16 = 0 -> addressable mx implb SZ_SPCI_IMPL -> fsobj H LF implb SZ_SPCI_IMPL ->
  (stb + SZ_SPCI_STATE <= implb \/ implb + SZ_SPCI_IMPL <= stb) ->
  AXStatics2 mx ->
