Definition sd_seg1_post (sp gp tp s6 s11 : word) (F : bvmap 5 word) (fc : bv 32) (LB : list block) (LF : list fframe)
    (stb ioc implb lo shi : Z) (S : statev) (ds : list byte) (ra s0 s1 s2 s3 s4 s5 s7 s8 s9 s10 : word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (spa ff fp : Z) (lowpad gap : list cell) (hjunk sh16 : list byte),
    ms' = MS (mkR (Z_to_bv 64 ASD_RETCV) (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa) (Z_to_bv 64 (fb_begin (st_fb S))) a1 a2 a3 a4 a5 a6 a7
                  (Z_to_bv 64 ff) (Z_to_bv 64 (stb + 32)) (Z_to_bv 64 (stb + 240)) (Z_to_bv 64 0) s6
                  (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 2147450880) (Z_to_bv 64 ff) (Z_to_bv 64 (Z.shiftr (stb + 240) 3 + 2147450880)) s11 t3 t4 t5 t6)
             F (Z_to_bv 64 ASD_BR) fc None m' (seg_rom bsegs)
    /\ munch (fs_W5 H lo (bv_unsigned sp) fp ff 1) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ (spa = bv_unsigned sp + -128 \/ spa = bv_unsigned sp + -144)
    /\ stk bsegs m' lo spa
    /\ rw_cells bsegs m' spa lowpad /\ Z.of_nat (cells_size lowpad) = 16
    /\ rw_cells bsegs m' (spa + 16) [C8 (Z_to_bv 64 ff)]
    /\ rw_cells bsegs m' (spa + 24) gap /\ Z.of_nat (cells_size gap) = bv_unsigned sp + -128 - spa
    /\ rw_cells bsegs m' (bv_unsigned sp + -104) (sd_saved s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra)
    /\ rw_cells bsegs m' ff [CB 120 hjunk; C8 (Z_to_bv 64 fp)]
    /\ rw_cells bsegs m' (Z.shiftr ff 3 + 2147450880) [CB 16 sh16]
    /\ rw_cells bsegs m' fp [C1 (b8 1)]
    /\ fresh_frame H LF 1 ff fp /\ as_RFS H ((1, ff, fp) :: LF) m' /\ ACONST m' /\ stack0 m' lo shi.

(* [comment removed for export] *)
Lemma sd_seg1 : forall (ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (m : mem) (LB : list block) (LF : list fframe) (stb ioc implb lo shi : Z) (S : statev) (ds : list byte),
  AStateBlock LB m stb ioc implb S ds -> fsobj H LF stb SZ_SPCI_STATE ->
  (st_fb S <> FB_empty -> fsobj H LF (fb_begin (st_fb S)) (fb_cap (st_fb S))) ->
  stk bsegs m lo (bv_unsigned sp) -> lo + 144 + AFS_STACK <= bv_unsigned sp -> aceil <= lo ->
  mem_inv bsegs m ->
  bv_unsigned sp mod 16 = 0 -> tp = Z_to_bv 64 ATP -> ACONST m -> athr_cells m ->
  as_RFS H LF m -> (length LF < AFS_MAXLIVE)%nat ->
  stack0 m lo shi -> bv_unsigned sp + 64 <= shi ->
  evt bsegs (sd_seg1_post sp gp tp s6 s11 F fc LB LF stb ioc implb lo shi S ds ra s0 s1 s2 s3 s4 s5 s7 s8 s9 s10 m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (stb + 32)) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
